-- P-81 Rites önerileri yeniden (1 Kasım): Supabase → SQL Editor'da bir kez çalıştır.
-- Öneri kartları senaryoya göre: tek iş, süre yok, saat yalnız işin kendisiyse; hazır öneri programı yok.
-- Kimlikler korunur; çıkan kartlar silinir. Uzmanın elle eklediği başka kartlar da silinir (liste dışı).

alter table public.icerik_kart add column if not exists hatirlatma text;
delete from public.icerik_program;
delete from public.icerik_kart where id not in ('h2', 'h3', 'h4', 'b1', 'b4', 'b3', 'u2', 'u3', 'z1', 'z2', 'a1', 'a2', 's1', 's2', 'o1', 'o2', 'i1', 'g1');

